import {
  DeleteObjectsCommand,
  GetObjectCommand,
  ListObjectsV2Command,
  NoSuchKey,
  PutObjectCommand,
  S3Client,
} from '@aws-sdk/client-s3';
import { Global, Inject, Injectable, Module } from '@nestjs/common';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import { APP_CONFIG, type AppConfig } from '../../config/config.module.js';

/**
 * Port for binary object storage (images). Keys are generated by the server only,
 * e.g. `businesses/<businessId>/<imageId>/thumb.webp`. S3 will be another implementation.
 */
export abstract class StorageProvider {
  abstract put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** Returns null if the object does not exist. */
  abstract get(key: string): Promise<Buffer | null>;
  abstract deletePrefix(prefix: string): Promise<void>;
}

const SAFE_KEY = /^[a-z0-9][a-z0-9/_.-]*$/;

export function assertSafeKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes('..') || key.includes('//')) {
    throw new Error(`Unsafe storage key: ${key}`);
  }
}

/** Development/test storage in a local folder. Refused in staging/production by config validation. */
@Injectable()
export class LocalDiskStorageProvider extends StorageProvider {
  private readonly root: string;

  constructor(@Inject(APP_CONFIG) config: AppConfig) {
    super();
    this.root = resolve(config.STORAGE_LOCAL_DIR);
  }

  /** The content type is not needed on disk (files are served with the type recorded by the caller). */
  async put(key: string, body: Buffer, _contentType: string): Promise<void> {
    const path = this.pathOf(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, body);
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.pathOf(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
  }

  async deletePrefix(prefix: string): Promise<void> {
    await rm(this.pathOf(prefix), { recursive: true, force: true });
  }

  private pathOf(key: string): string {
    assertSafeKey(key);
    const path = resolve(join(this.root, key));
    if (!path.startsWith(this.root + sep)) throw new Error(`Storage key escapes root: ${key}`);
    return path;
  }
}

/**
 * Private S3 bucket (Phase 9, ADR-0020). Objects are never public: the API reads them and serves
 * public images itself, exactly as with local disk, so nothing else changes. Credentials come
 * from the AWS default chain (the EC2 instance role in production), never from configuration.
 */
@Injectable()
export class S3StorageProvider extends StorageProvider {
  private readonly bucket: string;
  readonly client: S3Client;

  constructor(@Inject(APP_CONFIG) config: AppConfig) {
    super();
    if (!config.S3_BUCKET) throw new Error('S3_BUCKET is required for S3 storage');
    this.bucket = config.S3_BUCKET;
    this.client = new S3Client({
      region: config.S3_REGION,
      ...(config.S3_ENDPOINT ? { endpoint: config.S3_ENDPOINT } : {}),
      forcePathStyle: config.S3_FORCE_PATH_STYLE,
    });
  }

  async put(key: string, body: Buffer, contentType: string): Promise<void> {
    assertSafeKey(key);
    await this.client.send(
      new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: body, ContentType: contentType }),
    );
  }

  async get(key: string): Promise<Buffer | null> {
    assertSafeKey(key);
    try {
      const res = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
      return res.Body ? Buffer.from(await res.Body.transformToByteArray()) : null;
    } catch (error) {
      if (error instanceof NoSuchKey || (error as { name?: string }).name === 'NoSuchKey') return null;
      throw error;
    }
  }

  /** Deletes every object under `prefix/` (an image's sizes), 1,000 at a time. */
  async deletePrefix(prefix: string): Promise<void> {
    assertSafeKey(prefix);
    let token: string | undefined;
    do {
      const page = await this.client.send(
        new ListObjectsV2Command({ Bucket: this.bucket, Prefix: `${prefix}/`, ContinuationToken: token }),
      );
      const keys = (page.Contents ?? []).flatMap((o) => (o.Key ? [{ Key: o.Key }] : []));
      if (keys.length) {
        await this.client.send(
          new DeleteObjectsCommand({ Bucket: this.bucket, Delete: { Objects: keys, Quiet: true } }),
        );
      }
      token = page.IsTruncated ? page.NextContinuationToken : undefined;
    } while (token);
  }
}

@Global()
@Module({
  providers: [
    {
      provide: StorageProvider,
      inject: [APP_CONFIG],
      useFactory: (config: AppConfig): StorageProvider =>
        config.STORAGE_PROVIDER === 's3' ? new S3StorageProvider(config) : new LocalDiskStorageProvider(config),
    },
  ],
  exports: [StorageProvider],
})
export class StorageModule {}
